export interface EDLProject {
  format: "vertical" | "square" | "horizontal";
  width: number;
  height: number;
  fps: number;
  target_duration: number;
}

export interface EDLCreativeDirection {
  style: string;
  pace: "slow" | "medium" | "fast";
  tone: string;
  hook_strength_threshold?: number;
}

export interface EDLTimelineEntry {
  id: string;
  source: string;
  source_in: number;
  source_out: number;
  timeline_start: number;
  role: "hook" | "context" | "b_roll" | "ending";
  transition?: string;
  duration: number;
}

export interface EDLAudio {
  music?: string;
  ducking?: boolean;
  sound_effects?: Array<{
    timestamp: number;
    type: string;
    volume: number;
  }>;
}

export interface EDLGraphics {
  captions?: boolean;
  motion_titles?: boolean;
  lower_thirds?: boolean;
  kinetic_typography?: boolean;
}

export interface EditDecisionList {
  version: string;
  project: EDLProject;
  creative_direction: EDLCreativeDirection;
  timeline: EDLTimelineEntry[];
  audio?: EDLAudio;
  graphics?: EDLGraphics;
  metadata?: {
    generated_by: string;
    generated_at: string;
    source_footage: string[];
    total_duration: number;
  };
}

export interface ValidatedEditDecisionList extends EditDecisionList {
  validation: {
    valid: boolean;
    errors: string[];
    warnings: string[];
    checked_at: string;
  };
}

export interface TimelineCommand {
  id: string;
  type:
    | "create_sequence"
    | "import_media"
    | "insert_clip"
    | "create_marker"
    | "apply_effect"
    | "set_volume"
    | "export_sequence";
  params: Record<string, any>;
  validated: boolean;
  execution_order: number;
}

export interface MotionGraphicsCommand {
  id: string;
  type:
    | "create_composition"
    | "create_text_layer"
    | "create_shape_layer"
    | "set_keyframe"
    | "create_kinetic_typography"
    | "create_lower_thirds"
    | "create_animated_captions"
    | "export_alpha";
  params: Record<string, any>;
  validated: boolean;
}

export interface EDLValidationResult {
  valid: boolean;
  errors: string[];
  warnings: string[];
  commands: TimelineCommand[];
  motionCommands: MotionGraphicsCommand[];
}
